use xiom.io;

use xiom.string;
fn check_guess(secret: Int, guess_str: Str) -> Result[Str, Str] {
  let guess = string.str_to_int(guess_str);

  let g = match guess {
    Ok(n) => n,
    Err(_) => { return Err("That's not a number!"); }
  };

  if g == secret {
    return Ok("Correct!");
  }
  elif g > secret {
    return Ok("Too high!");
  }
  else {
    return Ok("Too low!");
  }
}

fn main() -> Int {
  match check_guess(50, "30") {
    Ok(hint) => { io.println(hint.to_str()); return 200; }
    Err(e) => { io.println(e.to_str()); return 400; }
  }
}
